if (-not (Get-AzResourceGroup -Name "rg-prod" -ErrorAction SilentlyContinue)) {
    New-AzResourceGroup -Name "rg-prod" -Location "eastus"
}
-- Safe to run any number of times: creates the resource group once, does nothing on every later run.

if (-not (Get-AzResourceGroup -Name "rg-prod" -ErrorAction SilentlyContinue)) {
    New-AzResourceGroup -Name "rg-prod" -Location "eastus"
}

data "azurerm_resource_group" "existing" {
  name = "rg-shared-networking"
}

resource "azurerm_virtual_network" "vnet" {
  name                = "vnet-ltv-demo"
  location            = data.azurerm_resource_group.existing.location
  resource_group_name = data.azurerm_resource_group.existing.name
  address_space       = ["10.0.0.0/16"]
}

if (-not (Get-AzStorageAccount -ResourceGroupName "rg-automation-demo" -Name "ltvdemostorage001" -ErrorAction SilentlyContinue)) {
    New-AzStorageAccount -ResourceGroupName "rg-automation-demo" -Name "ltvdemostorage001" -Location "eastus" -SkuName "Standard_LRS"
}

terraform {
  backend "s3" {
    bucket         = "ltv-terraform-state"
    key            = "prod/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
  }
}
-- A shared backend with locking, instead of three separate local state files.
